#!/usr/bin/env bash
# migration-baseline.sh generate TAG | check (migrations v2, step 5): the squashed baseline and the proof that it is the same schema.
#
#   generate TAG  replay the migration files of release tag TAG (from git, not from the working tree) in a throwaway Postgres and write
#                 `pg_dump --no-owner` of the result, schema, seed rows and grants, to internal/db/baseline/0000_baseline.sql.
#                 Never from prod: a baseline built from a live database would carry whatever drift that database has.
#   check         read the tag from the baseline's header, replay that tag's files again, and compare the two dumps after normalising
#                 (migration-dump-norm.py). A baseline that was edited by hand, or built from another tag, differs and fails.
#
# Postgres runs in docker, and pg_dump runs inside it, so the dump format is that server's major (BASELINE_PG_IMAGE, default the CI image;
# the pin to prod's CNPG image digest is one variable). Files that start with `-- migrate:no-transaction` run outside a transaction, the
# rest in one each, the same split the runner makes. The baseline lives outside internal/db/migrations, so the runner does not see it yet.
set -euo pipefail

cd "$(git rev-parse --show-toplevel)"
image="${BASELINE_PG_IMAGE:-postgres:16-alpine}"
baseline="internal/db/baseline/0000_baseline.sql"
dir="internal/db/migrations"
here="$(cd "$(dirname "$0")" && pwd)"
tmp=$(mktemp -d)
cid=""
cleanup() { [ -n "$cid" ] && docker rm -f "$cid" >/dev/null 2>&1; rm -rf "$tmp"; return 0; }
trap cleanup EXIT

# replay_tag TAG OUT: the raw dump of a fresh database after the tag's files.
replay_tag() {
  local tag="$1" out="$2" f
  mkdir -p "$tmp/files"
  rm -f "$tmp"/files/*.sql
  git ls-tree -r --name-only "$tag" -- "$dir" | grep -E '/[0-9]{4}_[^/]*\.sql$' | while read -r f; do
    git show "$tag:$f" > "$tmp/files/$(basename "$f")"
  done
  [ -n "$(ls "$tmp/files")" ] || { echo "migration-baseline: no migration files at $tag" >&2; exit 1; }
  cid=$(docker run -d --rm -e POSTGRES_PASSWORD=x -e POSTGRES_DB=base "$image")
  for _ in $(seq 1 60); do docker exec "$cid" pg_isready -U postgres -d base -q 2>/dev/null && break; sleep 1; done
  docker exec "$cid" pg_isready -U postgres -d base -q
  # A second readiness check: the entrypoint restarts the server once after its init scripts.
  sleep 2
  for _ in $(seq 1 30); do docker exec "$cid" psql -U postgres -d base -qtAc 'select 1' >/dev/null 2>&1 && break; sleep 1; done
  docker cp "$tmp/files" "$cid:/files"
  # The runner creates the bookkeeping table itself before the first file (migrate.go), and later files alter it.
  docker exec "$cid" psql -U postgres -d base -q -v ON_ERROR_STOP=1 -c \
    'CREATE TABLE IF NOT EXISTS migrations (id TEXT PRIMARY KEY, applied_at BIGINT NOT NULL, note TEXT)'
  for f in $(ls "$tmp/files" | sort); do
    if [ "$(head -n1 "$tmp/files/$f")" = "-- migrate:no-transaction" ]; then one=""; else one="-1"; fi
    docker exec "$cid" psql -U postgres -d base -q -v ON_ERROR_STOP=1 $one -f "/files/$f" >/dev/null \
      || { echo "migration-baseline: $f failed at $tag" >&2; exit 1; }
  done
  docker exec "$cid" pg_dump -U postgres -d base --no-owner --column-inserts > "$out"
  docker rm -f "$cid" >/dev/null 2>&1; cid=""
}

case "${1:-}" in
  generate)
    tag="${2:?tag}"
    git rev-parse -q --verify "refs/tags/$tag" >/dev/null || { echo "migration-baseline: no tag $tag (fetch tags)" >&2; exit 1; }
    replay_tag "$tag" "$tmp/raw.sql"
    {
      echo "-- baseline-of: $tag"
      echo "-- Generated by .github/scripts/migration-baseline.sh generate $tag from the tag's migration files, never from a live database."
      echo "-- Immutable like a migration. A new baseline comes from a later tag, in a PR that also proves it equals that tag's replay."
      grep -v '^\\' "$tmp/raw.sql" # psql meta lines (\restrict) would break a driver applying the file
    } > "$baseline"
    echo "migration-baseline: wrote $baseline from $tag"
    ;;
  check)
    [ -f "$baseline" ] || { echo "migration-baseline: no baseline yet, nothing to check"; exit 0; }
    tag=$(sed -n 's/^-- baseline-of: //p;1q' "$baseline" | head -n1)
    [ -n "$tag" ] || { echo "migration-baseline: $baseline has no '-- baseline-of: TAG' first line" >&2; exit 1; }
    git rev-parse -q --verify "refs/tags/$tag" >/dev/null || { echo "migration-baseline: tag $tag is not fetched" >&2; exit 1; }
    replay_tag "$tag" "$tmp/replay.sql"
    if python3 -I "$here/migration-dump-norm.py" "$baseline" "$tmp/replay.sql"; then
      echo "migration-baseline: $baseline equals the replay of $tag"
    else
      echo "migration-baseline: $baseline differs from the replay of $tag (lines: - baseline only, + replay only)" >&2
      exit 1
    fi
    ;;
  *) echo "usage: $0 generate TAG | check" >&2; exit 2 ;;
esac
